/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// Controller class for the order shipment bundling reporting job.
/// </summary>
class METOrderShipmentBundlingReportingJobController extends METPrintDestinationController
{
}

Method.Source:
/// <summary>
/// Constructs <c>METOrderShipmentBundlingReportingJobController</c>.
/// </summary>
/// <returns>
/// <c>METOrderShipmentBundlingReportingJobController</c>.
/// </returns>
public static METOrderShipmentBundlingReportingJobController construct()
{
    return new METOrderShipmentBundlingReportingJobController();
}

/// <summary>
/// Instantiates new object.
/// </summary>
void new()
{
    super(classStr(METOrderShipmentBundlingReportingJobService),
          methodStr(METOrderShipmentBundlingReportingJobService, process),
          SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Starts the process.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METOrderShipmentBundlingReportingJobController controller;

    controller = METOrderShipmentBundlingReportingJobController::construct();

    controller.init(_args);
    controller.startOperation();
}

/// <summary>
/// Initializes contoller and contract.
/// </summary>
/// <param name = "_args">Args.</param>
public void init(Args _args)
{
    METOrderShipmentBundlingReportingJobContract contract;
    METOrderTransactionType transactionType;
    WHSParameters whsParameter;

    whsParameter = WHSParameters::find();
    transactionType = _args.parmEnum();
    contract = this.getDataContractObject('_contract') as METOrderShipmentBundlingReportingJobContract;

    contract.initQuery(transactionType);

    if (transactionType == METOrderTransactionType::SalesOrder)
    {
        contract.parmThreadCount(whsParameter.METSalesOrderBundlingReportingJobThreadCount);
        this.parmDialogCaption("@MET:SalesOrderShipmentBundlingReportingJob");
    }
    else
    {
        contract.parmThreadCount(whsParameter.METTransferOrderBundlingReportingJobThreadCount);
        this.parmDialogCaption("@MET:TransferOrderShipmentBundlingReportingJob");
    }

    this.parmLoadFromSysLastValue(false);
}

/// <summary>
/// Description
/// </summary>
/// <returns>Default caption.</returns>
public ClassDescription defaultCaption()
{
    return "@MET:OrderShipmentBundlingReportingJob";
}
